#include <array>
#include <format>
#include <iostream>
#include <string>
#include <string_view>
#include <thread>
#include <vector>

struct Reading {
  std::string sensor;
  int samples = 0;
};

// name and samples are copied into the thread; slot is shared, so the caller passes std::ref.
void collect(std::string_view name, int samples, Reading& slot) {
  slot.sensor = std::string(name);
  slot.samples = samples;
}

int main() {
  const std::array<std::string_view, 3> sensors{"front_laser", "rear_laser", "imu"};
  std::vector<Reading> readings(sensors.size());
  {
    std::vector<std::jthread> workers;
    workers.reserve(sensors.size());
    for (std::ptrdiff_t i = 0; i < std::ssize(sensors); ++i) {
      workers.emplace_back(collect, sensors[i], 100 + static_cast<int>(i), std::ref(readings[i]));
    }
    std::cout << std::format("{} workers started; the scope ends and every jthread joins\n", workers.size());
  }
  for (const Reading& r : readings) std::cout << std::format("{}: {} samples\n", r.sensor, r.samples);
  std::cout << std::format("hardware_concurrency reports a positive number: {}\n",
                           std::thread::hardware_concurrency() > 0);
}

