// The work itself: no threads and no shared state, so a test can call it on its own.
[[nodiscard]] std::optional<float> nearest(std::span<const float> ranges) {
  const auto it = std::ranges::min_element(ranges);
  if (it == ranges.end()) return std::nullopt;
  return *it;
}

[[nodiscard]] std::vector<std::span<const float>> split(std::span<const float> all, std::ptrdiff_t parts) {
  std::vector<std::span<const float>> pieces;
  pieces.reserve(parts);
  const std::ptrdiff_t each = std::ssize(all) / parts;
  for (std::ptrdiff_t i = 0; i < parts; ++i) {
    const std::ptrdiff_t first = i * each;
    const std::ptrdiff_t count = i + 1 == parts ? std::ssize(all) - first : each;
    pieces.push_back(all.subspan(first, count));
  }
  return pieces;
}

int main() {
  constexpr std::ptrdiff_t kBeams = 3600;
  constexpr std::ptrdiff_t kWorkers = 4;
  std::vector<float> ranges(kBeams);
  for (std::ptrdiff_t i = 0; i < kBeams; ++i) {
    ranges[i] = 5.0F + static_cast<float>((i * 37) % 500) / 100.0F;
  }
  ranges[150] = 0.80F;  // one obstacle in each quarter of the scan
  ranges[1234] = 0.42F;
  ranges[2500] = 1.10F;
  ranges[3300] = 0.63F;

  const std::vector<std::span<const float>> parts = split(ranges, kWorkers);
  std::vector<std::optional<float>> found(parts.size());  // one slot per worker: nothing is shared
  {
    std::vector<std::jthread> workers;
    workers.reserve(parts.size());
    for (std::ptrdiff_t i = 0; i < std::ssize(parts); ++i) {
      workers.emplace_back([part = parts[i], slot = &found[i]] { *slot = nearest(part); });
    }
  }

  for (std::ptrdiff_t i = 0; i < std::ssize(found); ++i) {
    std::cout << std::format("chunk {}: {} beams, nearest {:.2f} m\n", i, std::ssize(parts[i]), found[i].value());
  }
  const auto best = std::ranges::min_element(found, {}, [](const std::optional<float>& v) { return v.value(); });
  std::cout << std::format("nearest over all {} beams: {:.2f} m\n", kBeams, best->value());
  std::cout << std::format("an empty scan has a nearest beam: {}\n", nearest({}).has_value());
}

