class TickCounter {
 public:
  void add(int ticks) {
    const std::lock_guard<std::mutex> lock(mutex_);
    total_ += ticks;
  }
  [[nodiscard]] int total() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return total_;
  }

 private:
  mutable std::mutex mutex_;
  int total_ = 0;
};

int main() {
  TickCounter counter;
  {
    std::vector<std::jthread> encoders;
    encoders.reserve(2);
    for (int i = 0; i < 2; ++i) {
      encoders.emplace_back([&counter] {
        for (int k = 0; k < 200'000; ++k) counter.add(1);
      });
    }
  }
  std::cout << std::format("400000 increments left the total at {}\n", counter.total());
}

