constexpr int kThreads = 4;
constexpr int kPerThread = 250'000;

// Runs one counting strategy on kThreads threads and prints how long it took and what it counted.
void measure(std::string_view label, const std::function<std::int64_t()>& strategy) {
  const auto start = std::chrono::steady_clock::now();
  const std::int64_t total = strategy();
  const auto elapsed = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start);
  std::cout << std::format("{:<22} {:>8.1f} ms  total {}\n", label, elapsed.count(), total);
}

int main() {
  measure("one mutex", [] {
    std::mutex mutex;
    std::int64_t total = 0;
    {
      std::vector<std::jthread> workers;
      workers.reserve(kThreads);
      for (int i = 0; i < kThreads; ++i) {
        workers.emplace_back([&mutex, &total] {
          for (int k = 0; k < kPerThread; ++k) {
            const std::lock_guard<std::mutex> lock(mutex);
            ++total;
          }
        });
      }
    }
    return total;
  });

  measure("one atomic", [] {
    std::atomic<std::int64_t> total = 0;
    {
      std::vector<std::jthread> workers;
      workers.reserve(kThreads);
      for (int i = 0; i < kThreads; ++i) {
        workers.emplace_back([&total] {
          for (int k = 0; k < kPerThread; ++k) total.fetch_add(1, std::memory_order_relaxed);
        });
      }
    }
    return total.load();
  });

  measure("a local, then merge", [] {
    std::mutex mutex;
    std::int64_t total = 0;
    {
      std::vector<std::jthread> workers;
      workers.reserve(kThreads);
      for (int i = 0; i < kThreads; ++i) {
        workers.emplace_back([&mutex, &total] {
          std::int64_t mine = 0;
          for (int k = 0; k < kPerThread; ++k) ++mine;
          const std::lock_guard<std::mutex> lock(mutex);
          total += mine;
        });
      }
    }
    return total;
  });
}

#include <cstdint>
#include <format>
#include <iostream>
#include <mutex>
#include <thread>

struct WheelTicks {
  std::int64_t left = 0;
  std::int64_t right = 0;
};

struct Odometry {
  std::int64_t left = 0;
  std::int64_t right = 0;
  std::int64_t samples = 0;
};

class WheelOdometry {
 public:
  void add(WheelTicks ticks) {
    const std::lock_guard<std::mutex> lock(mutex_);
    state_.left += ticks.left;
    state_.right += ticks.right;
    state_.samples += 1;
  }

  // Returns a copy, so the caller reads it long after the lock has gone.
  [[nodiscard]] Odometry snapshot() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return state_;
  }

 private:
  mutable std::mutex mutex_;
  Odometry state_;
};

int main() {
  constexpr std::int64_t kUpdates = 200'000;
  constexpr std::int64_t kSamples = 100'000;
  WheelOdometry odometry;
  std::int64_t inconsistent = 0;
  {
    std::jthread encoder([&odometry] {
      for (std::int64_t k = 0; k < kUpdates; ++k) odometry.add({.left = 1, .right = 3});
    });
    std::jthread reader([&odometry, &inconsistent] {
      for (std::int64_t k = 0; k < kSamples; ++k) {
        const Odometry seen = odometry.snapshot();
        if (seen.left != seen.samples || seen.right != 3 * seen.samples) ++inconsistent;
      }
    });
  }
  const Odometry final_state = odometry.snapshot();
  std::cout << std::format("{} updates: left {}, right {}, samples {}\n", kUpdates, final_state.left,
                           final_state.right, final_state.samples);
  std::cout << std::format("{} snapshots read while the encoder was writing, {} of them inconsistent\n", kSamples,
                           inconsistent);
}

