struct Ticks {
  std::int64_t count = 0;
};

class TopicTotals {
 public:
  void add(std::string_view topic, Ticks ticks) {
    const std::lock_guard<std::mutex> lock(mutex_);
    totals_[std::string(topic)] += ticks.count;
  }

  [[nodiscard]] std::optional<std::int64_t> total(std::string_view topic) const {
    const std::lock_guard<std::mutex> lock(mutex_);
    const auto it = totals_.find(std::string(topic));
    if (it == totals_.end()) return std::nullopt;
    return it->second;
  }

  // A copy, taken under the lock: the caller may read it for as long as it likes.
  [[nodiscard]] std::vector<std::pair<std::string, std::int64_t>> snapshot() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return {totals_.begin(), totals_.end()};
  }

 private:
  mutable std::mutex mutex_;
  std::map<std::string, std::int64_t> totals_;
};

int main() {
  constexpr int kWorkers = 4;
  constexpr int kPerWorker = 5'000;
  TopicTotals totals;
  {
    std::vector<std::jthread> workers;
    workers.reserve(kWorkers);
    for (int i = 0; i < kWorkers; ++i) {
      workers.emplace_back([&totals] {
        for (int k = 0; k < kPerWorker; ++k) {
          totals.add("/scan", {.count = 1});
          totals.add("/odom", {.count = 2});
        }
      });
    }
  }
  for (const auto& [topic, count] : totals.snapshot()) {
    std::cout << std::format("{}: {} ticks\n", topic, count);
  }
  std::cout << std::format("/scan total {}\n", totals.total("/scan").value());
  std::cout << std::format("/imu has a total: {}\n", totals.total("/imu").has_value());
}

