class ScanLog {
 public:
  void append(float range) {
    const std::lock_guard<std::mutex> lock(mutex_);
    ranges_.push_back(range);
  }

  // Wrong: the lock ends with the function, and the caller is left holding guarded data.
  [[nodiscard]] const float& newest() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return ranges_.back();
  }

 private:
  mutable std::mutex mutex_;
  std::vector<float> ranges_;
};

int main() {
  ScanLog log;
  log.append(1.5F);
  std::latch handed_out(2);
  std::latch grown(2);
  std::jthread reader([&log, &handed_out, &grown] {
    const float& seen = log.newest();
    handed_out.arrive_and_wait();
    grown.arrive_and_wait();
    std::cout << std::format("the reader sees {:.1f}\n", seen);
  });
  handed_out.arrive_and_wait();
  for (int k = 0; k < 1000; ++k) log.append(2.5F);  // the vector reallocates and frees its old block
  grown.arrive_and_wait();
}

