#include <cstdint>
#include <format>
#include <iostream>
#include <mutex>
#include <thread>

class Encoder {
 public:
  explicit Encoder(std::int64_t ticks) : ticks_(ticks) {}

  // scoped_lock takes both mutexes in one step, in whichever order avoids a deadlock.
  void move_to(Encoder& other, std::int64_t count) {
    const std::scoped_lock lock(mutex_, other.mutex_);
    ticks_ -= count;
    other.ticks_ += count;
  }

  [[nodiscard]] std::int64_t ticks() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return ticks_;
  }

 private:
  mutable std::mutex mutex_;
  std::int64_t ticks_ = 0;
};

int main() {
  Encoder left(1000);
  Encoder right(1000);
  {
    std::jthread one([&left, &right] {
      for (int k = 0; k < 20'000; ++k) left.move_to(right, 1);
    });
    std::jthread two([&left, &right] {
      for (int k = 0; k < 20'000; ++k) right.move_to(left, 1);
    });
  }
  std::cout << std::format("40000 moves in both directions: left {}, right {}, sum {}\n", left.ticks(),
                           right.ticks(), left.ticks() + right.ticks());
}

